namespace sv_078e5d08e63b4ff5868c2713c113f198;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(
    string Theme,
    string FontSize,
    string Language,
    bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <h4 class="mb-4">Profile Settings</h4>

    <div class="mb-4 d-flex align-items-center gap-3">
        <img src="@_avatarUrl" alt="Avatar" class="rounded-circle border"
             style="width:72px;height:72px;object-fit:cover;"
             @onerror="HandleAvatarError" />
        <div>
            <small class="text-muted d-block">Avatar URL</small>
            <code class="small">@_avatarUrl</code>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="displayName">Display Name</label>
        <input type="text" id="displayName" class="form-control" @bind="_displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="email">Email</label>
        <input type="email" id="email" class="form-control" @bind="_email" />
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="bio">Bio</label>
        <textarea id="bio" class="form-control" rows="4" @bind="_bio"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">
            Discard Changes
        </button>
    </div>
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _message = "Profile saved successfully!";
        _saving = false;
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }

        _message = null;
    }

    private void HandleAvatarError() { }
}

@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <h4 class="mb-4">Notification Preferences</h4>

    <div class="mb-4">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif"
                   checked="@_emailNotifications"
                   @onchange="e => _emailNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif"
                   checked="@_pushNotifications"
                   @onchange="e => _pushNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest"
                   checked="@_weeklyDigest"
                   @onchange="e => _weeklyDigest = (bool)e.Value!" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <h5 class="mb-3">Muted Channels</h5>
    <div class="mb-4">
        @foreach (var channel in _allChannels)
        {
            var isMuted = _mutedChannels.Contains(channel);
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                       checked="@isMuted"
                       @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                <label class="form-check-label" for="@($"ch-{channel}")">
                    <span class="me-1">#</span>@channel
                </label>
            </div>
        }
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @(_saving ? "Saving…" : "Save Preferences")
    </button>
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = [];
    private List<string> _allChannels = [];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = [.. prefs.MutedChannels];

        // Build a combined list of all known channels (muted + common defaults)
        var defaults = new[] { "general", "announcements", "engineering", "design", "marketing", "support" };
        _allChannels = [.. defaults.Union(prefs.MutedChannels).Distinct().Order()];

        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
        {
            _mutedChannels.Add(channel);
        }
        else if (!muted)
        {
            _mutedChannels.Remove(channel);
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _message = "Preferences saved successfully!";
        _saving = false;
    }
}

@inject ISettingsService SettingsService

@if (_loading)
{
    <div class="text-center p-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <h4 class="mb-4">Security Settings</h4>

    <!-- Change Password -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             role="button" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span class="fw-semibold">Change Password</span>
            <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
        </div>
        @if (_passwordPanelOpen)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label" for="currentPwd">Current Password</label>
                    <input type="password" id="currentPwd" class="form-control" @bind="_currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="newPwd">New Password</label>
                    <input type="password" id="newPwd" class="form-control" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label" for="confirmPwd">Confirm New Password</label>
                    <input type="password" id="confirmPwd" class="form-control" @bind="_confirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(_passwordMessage))
                {
                    <div class="alert @(_passwordError ? "alert-danger" : "alert-success")" role="alert">
                        @_passwordMessage
                    </div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating…" : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h5 class="mb-1">Two-Factor Authentication</h5>
                <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                @if (_lastPasswordChange.HasValue)
                {
                    <small class="text-muted ms-3">
                        Last password change: @_lastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </small>
                }
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@_twoFactorEnabled"
