        <div class="d-flex gap-3">
            @foreach (var theme in _themes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>
    </div>

    <!-- Font Size -->
    <div class="mb-4">
        <label class="form-label fw-semibold">Font Size</label>
        <div class="d-flex gap-3">
            @foreach (var size in _fontSizes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>
    </div>

    <!-- Language -->
    <div class="mb-4">
        <label class="form-label fw-semibold" for="language">Language</label>
        <select id="language" class="form-select" style="max-width:300px;"
                value="@_language" @onchange="e => _language = e.Value!.ToString()!">
            @foreach (var lang in _languages)
            {
                <option value="@lang.Code">@lang.Name</option>
            }
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode"
                   checked="@_compactMode"
                   @onchange="e => _compactMode = (bool)e.Value!" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="mb-4">
        <label class="form-label fw-semibold">Preview</label>
        <div class="border rounded @PreviewBackgroundClass" style="@PreviewStyle">
            <div class="@PreviewPaddingClass">
                <h5 class="@PreviewTextClass">Sample Heading</h5>
                <p class="@PreviewTextClass mb-2">
                    This is a preview of how your content will look with the selected settings.
                </p>
                <button class="btn btn-sm @PreviewButtonClass">Sample Button</button>
                <span class="badge @PreviewBadgeClass ms-2">Badge</span>
            </div>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @(_saving ? "Saving…" : "Save")
    </button>
}

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly (string Code, string Name)[] _languages =
    [
        ("en", "English"),
        ("es", "Español"),
        ("fr", "Français"),
        ("de", "Deutsch"),
        ("ja", "日本語"),
        ("zh", "中文")
    ];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance saved successfully!";
        _saving = false;
    }

    // Preview helpers
    private string PreviewStyle => $"font-size:{FontSizeCss};transition:all 0.2s ease;";
    private string FontSizeCss => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };
    private string PreviewBackgroundClass => _theme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };
    private string PreviewTextClass => _theme == "Dark" ? "text-light" : "text-dark";
    private string PreviewPaddingClass => _compactMode ? "p-2" : "p-3";
    private string PreviewButtonClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-dark";
    private string PreviewBadgeClass => _theme == "Dark" ? "bg-light text-dark" : "bg-dark";
}
"}

