                            break;
                        case "Notifications":
                            <NotificationsSection />
                            break;
                        case "Security":
                            <SecuritySection />
                            break;
                        case "Appearance":
                            <AppearanceSection />
                            break;
                    }
                </div>
            </div>
        </div>
    </div>
</div>

